{"implementation":"def solve(case):
    data = case.get("payload", case)
    segments = data["segments"]
    budget = data["budget"]

    allocations = {
        segment["name"]: segment["minimum"]
        for segment in segments
    }
    remaining = budget - sum(allocations.values())

    if remaining > 0:
        ranked = sorted(
            enumerate(segments),
            key=lambda item: (-item[1]["importance"], item[0]),
        )
        for _, segment in ranked:
            name = segment["name"]
            available = segment["capacity"] - allocations[name]
            amount = min(remaining, max(0, available))
            allocations[name] += amount
            remaining -= amount
            if remaining <= 0:
                break

    return {"allocations": allocations}
"}
